require("Common.TimeDate")
ShopItem = class("ShopItem")

function ShopItem:InitPanel(mGameObject)
    self.gameObject = mGameObject;
    self.transform = mGameObject.transform;
    self:FindComponent()
    ---加载后需要做什么写在这里

    self:Init();
end

function ShopItem:FindComponent()
    self.iconRoot = Util.FindChildEx(self.transform,"IconRoot");
    self.markObjRight = Util.FindChildEx(self.transform,"MarkRight").gameObject;
    self.markObjLeft = Util.FindChildEx(self.transform,"MarkLeft").gameObject;
    self.labelPrompt = Util.FindChildEx(self.transform,"Info/LabelPrompt"):GetComponent("UILabel");
    self.labelMarkRight = Util.FindChildEx(self.transform,"MarkRight/LabelMark"):GetComponent("UILabel");
    self.labelMarkLeft = Util.FindChildEx(self.transform,"MarkLeft/LabelMark"):GetComponent("UILabel");
    self.rechargeImage = Util.FindChildEx(self.transform,"RechargeImage"):GetComponent("UISprite");
    self.labelName = Util.FindChildEx(self.transform,"Info/LabelName"):GetComponent("UILabel");

    self.labelRechargePrice = Util.FindChildEx(self.transform,"Info/LabelRechargePrice"):GetComponent("UILabel");
    self.lineThrough = Util.FindChildEx(self.transform,"Info/LineThrough").gameObject;
    self.labelItemCount = Util.FindChildEx(self.transform,"Info/LabelItemCount"):GetComponent("UILabel");
    self.buttonBuyEvent = self.transform:Find("ButtonBuy"):GetComponent("UIEventTrigger");

    self.labelLimit = Util.FindChildEx(self.transform,"Info/LabelLimit"):GetComponent("UILabel");

    self.currencyImage = Util.FindChildEx(self.transform,"Info/CurrencyImage"):GetComponent("UISprite");
    self.labelItemPrice = Util.FindChildEx(self.transform,"Info/LabelItemPrice"):GetComponent("UILabel");
    self.discountObj = Util.FindChildEx(self.transform,"Info/DiscountImage").gameObject;
    self.labelDiscountPrice = Util.FindChildEx(self.transform,"Info/DiscountImage/LabelDiscountPrice"):GetComponent("UILabel");
end

function ShopItem:Init()
    EventDelegate.Add(self.buttonBuyEvent.onClick, EventDelegate.Callback(function() self:BuyOnClick() end));
end

