function ShopItem:SetItem(shopData, tab, index)
    self.shopData = shopData;
    self.tab = tab;
    self.index = index;
    local isRechargeTab = (tab == ShopTab.Recharge);
    local isRMB = (self.shopData.currency == 1);
    self.rechargeImage.gameObject:SetActive(isRechargeTab);
    self.labelRechargePrice.gameObject:SetActive(isRMB);
    self.labelItemPrice.gameObject:SetActive(not isRMB);
    self.currencyImage.gameObject:SetActive(not isRMB);
    self.iconRoot.gameObject:SetActive(not isRechargeTab);
    self.markObjLeft:SetActive(not isRechargeTab);
    self.labelPrompt.gameObject:SetActive(not isRechargeTab);
    self.labelLimit.gameObject:SetActive(false);

    self.labelName.text = GameLogic.GetItemName(self.shopData.reward.type[1], self.shopData.reward.id[1]);
    if (self.shopData.reward.num[1] > 1) then
        self.labelItemCount.gameObject:SetActive(true);
        self.labelItemCount.text = "x" .. self.shopData.reward.num[1];
    else
        self.labelItemCount.gameObject:SetActive(false);
    end

    --货币
    --折扣划线
    self.labelItemPrice.transform.localPosition = Vector3.New(18, self.labelItemPrice.transform.localPosition.y, 0);
    if (self.shopData.currency == 1) then
        self.labelRechargePrice.text = TextSystem.GetText("currency_sign") .. self.shopData.price;
        self.lineThrough:SetActive(false);
        self.discountObj:SetActive(false);
    else
        if (self.shopData.currency == 3) then
            self.currencyImage.spriteName = "gold";
        else
            self.currencyImage.spriteName = "diamond";
        end

        if (self.shopData.discount ~= nil and self.shopData.discount ~= 0) then
            local discountPrice = math.floor(self.shopData.price * self.shopData.discount);
            self.labelItemPrice.text = self.shopData.price;
            self.labelDiscountPrice.text = discountPrice;
            self.labelItemPrice.fontSize = 20;
            self.lineThrough:SetActive(true);
            self.discountObj:SetActive(true);
            self.labelItemPrice.transform.localPosition = Vector3.New(-10, self.labelItemPrice.transform.localPosition.y, 0);
        else
            self.labelItemPrice.text = self.shopData.price;
            self.labelItemPrice.fontSize = 23;
            self.lineThrough:SetActive(false);
            self.discountObj:SetActive(false);
        end
    end

    if (isRechargeTab) then--充值
        if (tonumber(self.shopData.isFirst) == 1) then
            self.rechargeImage.spriteName = "shouchong_" .. self.shopData.id;
            self.labelMarkRight.text = TextSystem.GetText("double");
            self.markObjRight:SetActive(true);
        else
            self.rechargeImage.spriteName = "yuanbao_" .. self.shopData.id;
            self.markObjRight:SetActive(false);
        end
        self.rechargeImage:MakePixelPerfect();
    else
        --图片
        self.mIconItem = ItemHelper.CreateAdaptedIconItem(self.shopData.reward.type[1], self.shopData.reward.id[1]);
        ItemHelper.GetIconItem(self.mIconItem, self.iconRoot);
        
        --右标签
        --1限次 2免费 3限量 4折扣
        self.markObjRight:SetActive(self.shopData.label ~= 0);
        if (self.shopData.label == 1) then
            self.labelMarkRight.text = TextSystem.GetText("shop_label_1");
        elseif (self.shopData.label == 2) then
            self.labelMarkRight.text = TextSystem.GetText("shop_label_2");
        elseif (self.shopData.label == 3) then
            self.labelMarkRight.text = TextSystem.GetText("shop_label_3");
        elseif (self.shopData.label == 4) then
            self.labelMarkRight.text = string.format("%s%s", self.shopData.discount * 10, TextSystem.GetText("shop_label_4"));
        end

        --次数、数量显示，左标签
        self:RefreshCount();

        --上下架时间
        self:UpdateTime();
    end
end

function ShopItem:RefreshCount()
    self.markObjLeft:SetActive(true);
    if (self.shopData.times ~= 0) then--单人限次
        self.labelMarkLeft.text = string.format("%s/%s", self.shopData.times - self.shopData.buyTimes, self.shopData.times);
    elseif (self.shopData.dailyTimes ~= 0) then--每日限次
        self.labelMarkLeft.text = string.format("%s/%s", self.shopData.dailyTimes - self.shopData.buyDailyTimes, self.shopData.dailyTimes);
    elseif (self.shopData.limit ~= 0) then--限量
        self.labelLimit.gameObject:SetActive(true);
        self.labelLimit.text = string.format("%s%s", TextSystem.GetText("shop_item_prompt_left"), self.shopData.limit - self.shopData.buyLimit);
        self.markObjLeft:SetActive(false);
    else
        self.labelMarkLeft.text = "";
        self.markObjLeft:SetActive(false);
    end
end

--刷新上下架时间
function ShopItem:UpdateTime()
    if (self.shopData ~= nil) then
        local hasOnOffTime = false;
        if (self.shopData.onTime ~= 0) then--有上架时间
            local currentServerTimeMS = GameLogic.CurrentServerTimeMS();
            if (self.shopData.offTime ~= 0) then--有下架时间
                local onTimeMS = TimeDate.DateBeginToMS(self.shopData.onTime);
                local offTimeMS = TimeDate.DateBeginToMS(self.shopData.offTime);
                local inRange = TimeDate.AnyTimeInRangeMS(onTimeMS, offTimeMS, currentServerTimeMS);
                if (inRange == -1) then --未到上架时间
                    self.labelPrompt.text = string.format("%s%s",
                            TextSystem.GetText("shop_item_prompt_on"),
                            CommonTools.TimeToFormat2(onTimeMS - currentServerTimeMS, false, true, true));
                    hasOnOffTime = true;
                elseif (inRange == 0) then --在上下架时间之间
                    self.labelPrompt.text = string.format("%s%s",
                            TextSystem.GetText("shop_item_prompt_off"),
                            CommonTools.TimeToFormat2(offTimeMS - currentServerTimeMS, false, true, true));
                    hasOnOffTime = true;
                elseif (inRange == 1) then --已过下架时间
                    self.labelPrompt.text = TextSystem.GetText("shop_item_prompt_removed");
                    hasOnOffTime = true;
                else
                    self.labelPrompt.text = "";
                end
            else--没有下架时间
                if (TimeDate.TimeCompareMS(currentServerTimeMS, TimeDate.DateBeginToMS(self.shopData.onTime)) == -1) then--未到上架时间
                    local onTimeMS = TimeDate.DateBeginToMS(self.shopData.onTime);
                    self.labelPrompt.text = string.format("%s%s",
                            TextSystem.GetText("shop_item_prompt_on"),
                            CommonTools.TimeToFormat2(onTimeMS - currentServerTimeMS, false, true, true));
                    hasOnOffTime = true;
                else
                    self.labelPrompt.text = "";
                end
            end
        end
        self.labelPrompt.gameObject:SetActive(hasOnOffTime);
    end
end

function ShopItem:BuyOnClick()
    if (self.tab == ShopTab.Recharge) then
        self:RealBuyOnClick();
    else
        if (self.shopData.price ~= 0) then
            if (self.shopData.limit ~= nil and self.shopData.limit ~= 0) then--限量
                HttpNetworkManager.ShopLimit(self.tab, self.shopData.id, function (rawData)
                    local data = cjson.decode(rawData);
                    if (tonumber(data.code) == NetworkConst.CODE_OK) then
                        self.shopData.buyLimit = data.buyLimit;
                        self.labelLimit.text = string.format("%s%s", TextSystem.GetText("shop_item_prompt_left"), self.shopData.limit - self.shopData.buyLimit);
                        ShopUIView.Instance():ShowDetailWindow(self);
                    end
                end);
            else
                if (self.shopData.times ~= 0 and self.shopData.buyTimes == self.shopData.times
                        or self.shopData.dailyTimes ~= 0 and self.shopData.buyDailyTimes == self.shopData.dailyTimes) then
                    self:RealBuyOnClick();
                else
                    ShopUIView.Instance():ShowDetailWindow(self);
                end
            end
        else
            self:RealBuyOnClick();
        end
    end
end

function ShopItem:RealBuyOnClick()
    if (self.tab == ShopTab.Recharge) then
        if (self.shopData.currency == 1) then--人民币购买
            HttpNetworkManager.PayStart(Player.uid, self.shopData.id, function (rawData)
                local data = cjson.decode(rawData);
                if (tonumber(data.code) == NetworkConst.CODE_OK) then
                    self:Recharge(data.orderGo, data.payCallback);
                end
            end);
        end
    else
        if (self.shopData.limit == nil or self.shopData.limit == 0 or self.shopData.limit - self.shopData.buyLimit > 0) then
            if (self.shopData.currency == 1) then--人民币购买
                HttpNetworkManager.PayShopBuy(Player.uid, self.shopData.id, function (rawData)
                    local data = cjson.decode(rawData);
                    if (tonumber(data.code) == NetworkConst.CODE_OK) then
                        self:Recharge(data.orderGo, data.payCallback);
                    end
                end);
            else
                HttpNetworkManager.ShopBuy(self.tab, self.shopData.id, function (rawData)
                    local data = cjson.decode(rawData);
                    if (tonumber(data.code) == NetworkConst.CODE_OK) then
                        RewardManager.ReceiveItems(data.reward);
                        RewardManager.ReceiveItems(data.consume, true);
                        self.shopData.buyLimit = data.item.buyLimit;
                        self.shopData.buyTimes = data.item.buyTimes;
                        self.shopData.buyDailyTimes = data.item.buyDailyTimes;
                        self:RefreshCount();
                    end
                end);
            end
        end
    end
end

function ShopItem:Recharge(orderId, payCallback)
    Debug.LogWarning("订单价格1:"..self.shopData.price);
    local order = UserSystem.Order.New();
    order.id = orderId;--订单号
    order.name = self.labelName.text;
    order.desc = "";
    order.price = self.shopData.price;
    order.amount = self.shopData.reward.num[1];--商品中的數字，比如：1000元寶的1000
    order.number = 1;--數量
    order.url = payCallback;
    order.extra = "";
    Debug.LogWarning("订单价格2:"..order.price);
    Debug.LogWarning("开始测试支付:"..tostring(order:GetJsonString()));
    userSystem.Instance:SDKPay(order);
end
